const collator=new Intl.Collator("fr",{numeric:true,sensitivity:"base"});document.querySelectorAll("[data-enhanced-table]").forEach((section)=>{const input=section.querySelector("[data-table-search]");const filters=Array.from(section.querySelectorAll("[data-table-filter]"));const table=section.querySelector("table");const tbody=section.querySelector("tbody");const rows=Array.from(tbody.querySelectorAll("tr[data-table-row]"));const count=section.querySelector("[data-row-count]");const noResults=section.querySelector("[data-no-results]");const totalColumns=Array.from(section.querySelectorAll("[data-total-column]"));function detailRow(row){if(!row.dataset.detailRowId){return null;}return document.getElementById(row.dataset.detailRowId);}function rowToggleButton(row){return row.querySelector("[data-row-toggle-button]");}function setRowExpanded(row,expanded){const detail=detailRow(row);const toggle=rowToggleButton(row);if(!detail||!toggle){return;}toggle.setAttribute("aria-expanded",String(expanded));detail.hidden=!expanded;}function updateCount(){const visibleRows=rows.filter((row)=>!row.hidden).length;if(count){count.textContent=`${visibleRows} / ${rows.length}`;}noResults.style.display=visibleRows===0?"block":"none";}function updateColumnTotals(){totalColumns.forEach((header)=>{const column=Number(header.dataset.totalColumn);const total=rows.reduce((sum,row)=>{if(row.hidden){return sum;}const cell=row.cells[column];const value=Number(cell?.dataset.sortValue??0);return value>0?sum+value:sum;},0);const target=header.querySelector("[data-column-total]");if(target){target.textContent=formatDuration(total);}});}function applyTableFilters(){const query=input?input.value.trim().toLocaleLowerCase("fr"):"";rows.forEach((row)=>{const matchesSearch=rowMatchesSearch(row,query);const matchesFilters=rowMatchesFilters(row,filters);row.hidden=!(matchesSearch&&matchesFilters);if(row.hidden){setRowExpanded(row,false);}});updateAvailableFilterOptions(query,filters,rows);updateCount();updateColumnTotals();}if(input){input.addEventListener("input",applyTableFilters);}if(filters.length){filters.forEach((filter)=>{filter.addEventListener("change",()=>{updateFilterSummary(filter);applyTableFilters();});updateFilterSummary(filter);});}section.addEventListener("toggle",(event)=>{const openedMenu=event.target.closest(".table-filter-menu[open]");if(!openedMenu){return;}filters.forEach((filter)=>{const menu=filter.querySelector(".table-filter-menu");if(menu&&menu!==openedMenu){menu.open=false;}});},true);function applySort(button,forcedDirection){const column=Number(button.dataset.sortColumn);const type=button.dataset.sortType||"text";const current=button.dataset.sortDirection||"none";const direction=forcedDirection||(current==="asc"?"desc":"asc");section.querySelectorAll("[data-sort-column]").forEach((other)=>{other.dataset.sortDirection="none";other.querySelector(".sort-indicator").className="sort-indicator";other.closest("th").setAttribute("aria-sort","none");});button.dataset.sortDirection=direction;button.querySelector(".sort-indicator").className=direction==="asc"?"sort-indicator mdi mdi-arrow-up":"sort-indicator mdi mdi-arrow-down";button.closest("th").setAttribute("aria-sort",direction==="asc"?"ascending":"descending",);rows.sort((left,right)=>{const leftValue=sortValue(left,column,type);const rightValue=sortValue(right,column,type);const comparison=type==="number"?leftValue-rightValue:collator.compare(leftValue,rightValue);return direction==="asc"?comparison:-comparison;}).forEach((row)=>{tbody.appendChild(row);const detail=detailRow(row);if(detail){tbody.appendChild(detail);}});}section.querySelectorAll("[data-sort-column]").forEach((button)=>{button.addEventListener("click",()=>{applySort(button);});});if(table.dataset.defaultSortColumn){const defaultButton=section.querySelector(`[data-sort-column="${table.dataset.defaultSortColumn}"]`,);if(defaultButton){applySort(defaultButton,table.dataset.defaultSortDirection||"asc");}}section.querySelectorAll("[data-row-toggle]").forEach((row)=>{row.addEventListener("click",(event)=>{if(event.target.closest("a, button, input, select, textarea, label")){return;}const toggle=rowToggleButton(row);const expanded=toggle.getAttribute("aria-expanded")==="true";setRowExpanded(row,!expanded);});});section.querySelectorAll("[data-row-toggle-button]").forEach((button)=>{button.addEventListener("click",()=>{const row=button.closest("[data-table-row]");const expanded=button.getAttribute("aria-expanded")==="true";setRowExpanded(row,!expanded);});});applyTableFilters();});document.addEventListener("click",(event)=>{document.querySelectorAll(".table-filter-menu[open]").forEach((menu)=>{if(!menu.contains(event.target)){menu.open=false;}});});document.addEventListener("keydown",(event)=>{if(event.key!=="Escape"){return;}document.querySelectorAll(".table-filter-menu[open]").forEach((menu)=>{menu.open=false;});});function sortValue(row,column,type){const cell=row.cells[column];const value=cell.dataset.sortValue||cell.textContent.trim();return type==="number"?Number(value||0):value;}function formatDuration(seconds){return`${(seconds/3600).toFixed(2)} h`;}function selectedFilterValues(filter){return new Set(Array.from(filter.querySelectorAll("[data-filter-option]:checked")).map((option)=>option.value,),);}function rowMatchesSearch(row,query){return!query||row.dataset.search.includes(query);}function rowMatchesFilters(row,filters,ignoredFilter=null){return filters.every((filter)=>{if(filter===ignoredFilter){return true;}const selectedValues=selectedFilterValues(filter);if(!selectedValues.size){return true;}return selectedValues.has(filterCellValue(row,filter));});}function filterCellValue(row,filter){const cell=row.cells[Number(filter.dataset.filterColumn)];return cell.textContent.trim().toLocaleLowerCase("fr");}function updateAvailableFilterOptions(query,filters,rows){filters.forEach((filter)=>{const availableValues=new Set(rows.filter((row)=>{return rowMatchesSearch(row,query)&&rowMatchesFilters(row,filters,filter);}).map((row)=>filterCellValue(row,filter)),);filter.querySelectorAll("[data-filter-option]").forEach((option)=>{option.disabled=!option.checked&&!availableValues.has(option.value);});});}function updateFilterSummary(filter){const summary=filter.querySelector("[data-filter-summary]");if(!summary){return;}const selectedOptions=Array.from(filter.querySelectorAll("[data-filter-option]:checked"),);if(!selectedOptions.length){summary.textContent=filter.dataset.filterPlaceholder;return;}if(selectedOptions.length===1){const label=selectedOptions[0].closest("label");summary.textContent=label?label.textContent.trim():selectedOptions[0].value;return;}summary.textContent=(filter.dataset.filterSelectedLabel||"{count} selected").replace("{count}",selectedOptions.length);}
